class Solution {
    public int minDistance(String word1, String word2) {
        return f(word1, word2, word1.length(), word2.length());
    }

    private int f(String a, String b, int i, int j) {
        if (i == 0) return j;
        if (j == 0) return i;
        if (a.charAt(i - 1) == b.charAt(j - 1)) return f(a, b, i - 1, j - 1);
        int insert = f(a, b, i, j - 1);
        int delete = f(a, b, i - 1, j);
        int replace = f(a, b, i - 1, j - 1);
        return 1 + Math.min(insert, Math.min(delete, replace));
    }
}

class Solution {
    public int minDistance(String word1, String word2) {
        int m = word1.length();
        int n = word2.length();
        int[][] dp = new int[m + 1][n + 1];

        for (int i = 0; i <= m; i++) dp[i][0] = i;
        for (int j = 0; j <= n; j++) dp[0][j] = j;

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (word1.charAt(i - 1) == word2.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1];
                } else {
                    int best = Math.min(dp[i][j - 1], dp[i - 1][j]);
                    best = Math.min(best, dp[i - 1][j - 1]);
                    dp[i][j] = 1 + best;
                }
            }
        }
        return dp[m][n];
    }
}

class Solution {
    public int minDistance(String word1, String word2) {
        if (word2.length() > word1.length()) {
            String t = word1;
            word1 = word2;
            word2 = t;
        }
        int m = word1.length();
        int n = word2.length();
        int[] dp = new int[n + 1];
        for (int j = 0; j <= n; j++) dp[j] = j;

        for (int i = 1; i <= m; i++) {
            int prev = i - 1;
            dp[0] = i;
            for (int j = 1; j <= n; j++) {
                int temp = dp[j];
                if (word1.charAt(i - 1) == word2.charAt(j - 1)) {
                    dp[j] = prev;
                } else {
                    int best = Math.min(dp[j - 1], temp);
                    best = Math.min(best, prev);
                    dp[j] = 1 + best;
                }
                prev = temp;
            }
        }
        return dp[n];
    }
}
